Ltac flagfix := repeat match goal with
  | |- context [Z.land (Z.lxor (Z.b2z ?b) 1) 1] => rewrite (land1_small (Z.lxor (Z.b2z b) 1)) by (apply lxor1_range; apply b2z_range)
  | |- context [Z.land (Z.b2z ?b) 1] => rewrite (land1_small (Z.b2z b)) by (apply b2z_range)
  end.
Ltac flag_range := first [ apply lxor1_range; apply b2z_range | apply b2z_range | lia ].

